# Let's verify the K4s found
edges_set = set(edges)

def verify_k4(vertices):
    for u, v in combinations(vertices, 2):
        if (u, v) not in edges_set and (v, u) not in edges_set:
            return False, (u, v)
    return True, None

for k4 in k4s:
    ok, missing = verify_k4(k4)
    print(f"K4 {k4}: valid={ok}")

